CONSOLE_CSS = """
<style>
/* =====================================================================
   SIH26166 demo console - the ONE injected style block.
   Everything load-bearing (type size, contrast, the state header, the
   metric rail) hangs off .ops-* classes on OUR OWN markup. Streamlit's
   data-testid selectors are used only for chrome and tone, so a Streamlit
   rename degrades the polish and never the legibility.
   If this block ever has to be removed under time pressure, delete the
   single st.markdown(CONSOLE_CSS, ...) call - the app still works.
   ASCII only. This repo has already had a UTF-8 dash mangled by a merge.
   ===================================================================== */

:root {
  /* --- ground and surfaces --- */
  --c-ground:      #F4F3EF;   /* page. warm off-white; pure white blooms */
  --c-surface:     #FFFFFF;   /* data panels */
  --c-chassis:     #E6E4DE;   /* sidebar, table headers, log blocks */
  --c-rule:        #CFCBC1;   /* hairline */
  --c-rule-strong: #8C877C;   /* section and header rules */

  /* --- ink --- */
  --c-ink:   #14181C;         /* primary text        ~15:1 on ground */
  --c-ink-2: #454C53;         /* secondary sentences ~8.4:1 */
  --c-ink-3: #5F666D;         /* labels, units       ~5.0:1 */

  /* --- accent --- */
  --c-accent:      #1F4B73;   /* ~8.6:1 on white */
  --c-accent-soft: #E3EAF1;

  /* --- status. word first, colour second. none lighter than 4.6:1 --- */
  --c-ok:    #1B6B3A;  --c-ok-bg:   #E8F0EA;
  --c-warn:  #8A5300;  --c-warn-bg: #F5EBDC;
  --c-stop:  #A01B1B;  --c-stop-bg: #F6E4E4;
  --c-null:  #5F666D;  --c-null-bg: #EBEAE7;

  /* --- type. offline stacks; both families ship with Windows 11 --- */
  --f-ui:   "Segoe UI Variable Text","Segoe UI",system-ui,-apple-system,
            "Helvetica Neue",Arial,sans-serif;
  --f-mono: Consolas,"Cascadia Mono","Cascadia Code",ui-monospace,
            "DejaVu Sans Mono","Liberation Mono",Menlo,monospace;

  --t-label:   11px;  /* uppercase, letterspaced */
  --t-micro:   13px;
  --t-body:    16px;
  --t-lede:    18px;
  --t-section: 14px;
  --t-state:   20px;
  --t-value:   28px;
  --t-hero:    40px;

  /* --- spacing scale, 4px base --- */
  --s0: 2px; --s1: 4px; --s2: 8px;  --s3: 12px;
  --s4: 16px; --s5: 24px; --s6: 32px; --s7: 48px;
}

/* ---------------------------------------------------------------- chrome */
[data-testid="stToolbar"], #MainMenu, footer,
[data-testid="stStatusWidget"], [data-testid="stHeaderActionElements"],
[data-testid="stDecoration"] { display: none !important; }

/* Header is flattened, NOT display:none - the sidebar collapse control
   lives in it on some versions and losing it strands a collapsed sidebar. */
header[data-testid="stHeader"] { background: transparent; height: 0; }

/* ---------------------------------------------------------------- canvas */
html, body, [data-testid="stAppViewContainer"] {
  background: var(--c-ground);
  color: var(--c-ink);
  font-family: var(--f-ui);
  font-size: var(--t-body);
  -webkit-font-smoothing: antialiased;
}
[data-testid="stMainBlockContainer"], .block-container {
  max-width: 1680px;
  padding: var(--s3) var(--s6) var(--s7) var(--s6);
}
p, li { font-size: var(--t-body); line-height: 1.45; color: var(--c-ink-2); }
[data-testid="stCaptionContainer"], [data-testid="stCaptionContainer"] p {
  font-size: var(--t-micro); line-height: 1.4; color: var(--c-ink-3);
}
code, kbd, pre, [data-testid="stCode"] {
  font-family: var(--f-mono);
  font-variant-numeric: tabular-nums;
}
a, a:visited { color: var(--c-accent); text-underline-offset: 2px; }

/* ------------------------------------------------------- persistent header */
.ops-hdr {
  position: sticky; top: 0; z-index: 99;          /* delete if it jitters */
  display: flex; flex-wrap: wrap; align-items: stretch;
  background: var(--c-surface);
  border: 1px solid var(--c-rule);
  border-bottom: 2px solid var(--c-rule-strong);
  margin: 0 0 var(--s5) 0;
}
.ops-hdr .cell {
  flex: 1 1 auto; min-width: 132px;
  padding: var(--s3) var(--s4);
  border-left: 1px solid var(--c-rule);
}
.ops-hdr .cell:first-child { border-left: 0; }
.ops-hdr .cell.ident { flex: 0 0 auto; min-width: 260px; background: var(--c-chassis); }
.ops-hdr .cell.wide  { flex: 2 1 320px; }
.ops-hdr .k {
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 600;
  letter-spacing: 0.09em; text-transform: uppercase;
  color: var(--c-ink-3); display: block; margin-bottom: var(--s1);
}
.ops-hdr .v {
  font-family: var(--f-mono); font-size: var(--t-state); line-height: 1.15;
  color: var(--c-ink); font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}
.ops-hdr .v.sm  { font-size: var(--t-micro); line-height: 1.35; color: var(--c-ink-2); }
.ops-hdr .v.dim { color: var(--c-ink-3); }
.ops-hdr .sys {
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 600;
  letter-spacing: 0.16em; color: var(--c-ink-3); text-transform: uppercase;
}
.ops-hdr .name { font-size: var(--t-lede); font-weight: 600; color: var(--c-ink); }

/* ------------------------------------------------------------- section rule */
.ops-sec {
  display: flex; align-items: baseline; gap: var(--s3);
  margin: var(--s6) 0 var(--s3) 0;
  border-bottom: 2px solid var(--c-rule-strong);
  padding-bottom: var(--s2);
}
.ops-sec .n {
  font-family: var(--f-mono); font-size: var(--t-section); font-weight: 700;
  color: var(--c-accent); letter-spacing: 0.04em;
}
.ops-sec .t {
  font-family: var(--f-mono); font-size: var(--t-section); font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--c-ink);
}
.ops-sec .sub {
  margin-left: auto; font-family: var(--f-mono); font-size: var(--t-label);
  letter-spacing: 0.08em; text-transform: uppercase; color: var(--c-ink-3);
}

/* --------------------------------------------------------------- verdict rail */
.ops-verdict {
  border: 1px solid var(--c-rule); border-left-width: 4px;
  background: var(--c-surface);
  padding: var(--s3) var(--s4); margin: var(--s3) 0 var(--s4) 0;
}
.ops-verdict .state {
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 700;
  letter-spacing: 0.12em; text-transform: uppercase;
  display: block; margin-bottom: var(--s1);
}
.ops-verdict .msg { font-size: var(--t-body); line-height: 1.45; color: var(--c-ink-2); }
.ops-verdict[data-state="ok"]   { border-left-color: var(--c-ok);   background: var(--c-ok-bg); }
.ops-verdict[data-state="ok"]   .state { color: var(--c-ok); }
.ops-verdict[data-state="warn"] { border-left-color: var(--c-warn); background: var(--c-warn-bg); }
.ops-verdict[data-state="warn"] .state { color: var(--c-warn); }
.ops-verdict[data-state="stop"] { border-left-color: var(--c-stop); background: var(--c-stop-bg); }
.ops-verdict[data-state="stop"] .state { color: var(--c-stop); }
.ops-verdict[data-state="null"] { border-left-color: var(--c-null); background: var(--c-null-bg); }
.ops-verdict[data-state="null"] .state { color: var(--c-null); }

/* ------------------------------------------------------------- metric rail */
.ops-rail { border: 1px solid var(--c-rule); background: var(--c-surface); }
.ops-row {
  display: flex; align-items: center; gap: var(--s4);
  padding: var(--s3) var(--s4);
  border-top: 1px solid var(--c-rule);
}
.ops-row:first-child { border-top: 0; }
.ops-row .name {
  flex: 0 0 240px;
  font-family: var(--f-mono); font-size: var(--t-micro); font-weight: 600;
  color: var(--c-ink);
}
.ops-row .val {
  flex: 0 0 260px; text-align: right;
  font-family: var(--f-mono); font-size: var(--t-value); line-height: 1.1;
  font-variant-numeric: tabular-nums; color: var(--c-ink);
}
.ops-row .val.na { font-size: var(--t-micro); color: var(--c-ink-3); text-align: right; }
.ops-row .mean { flex: 1 1 auto; font-size: var(--t-micro); color: var(--c-ink-3); }
.ops-row .gate {
  flex: 0 0 190px; text-align: right;
  font-family: var(--f-mono); font-size: var(--t-micro); font-weight: 700;
  letter-spacing: 0.06em;
}
.ops-row .gate .word { display: inline-block; padding-right: var(--s2); }
.ops-row .gate .thr  { font-weight: 400; color: var(--c-ink-3); }
.ops-row[data-gate="pass"] .gate .word { color: var(--c-ok); }
.ops-row[data-gate="fail"] .gate .word { color: var(--c-stop); }
/* second channel: a PASS row carries a left rule, a FAIL row a doubled one */
.ops-row[data-gate="pass"] { box-shadow: inset 3px 0 0 var(--c-ok); }
.ops-row[data-gate="fail"] { box-shadow: inset 3px 0 0 var(--c-stop),
                                         inset 7px 0 0 var(--c-surface),
                                         inset 10px 0 0 var(--c-stop); }

/* ------------------------------------------------------------- hero figure */
.ops-figure {
  border: 1px solid var(--c-rule); border-top: 3px solid var(--c-accent);
  background: var(--c-surface); padding: var(--s4) var(--s5); margin: var(--s4) 0;
}
.ops-figure .big {
  font-family: var(--f-mono); font-size: var(--t-hero); line-height: 1.05;
  font-variant-numeric: tabular-nums; color: var(--c-ink);
}
.ops-figure .unit { font-size: var(--t-lede); color: var(--c-ink-3); padding-left: var(--s2); }
.ops-figure .qual { font-size: var(--t-micro); color: var(--c-ink-2); margin-top: var(--s2); }

/* ---------------------------------------------------------- reliability census */
.ops-census { border: 1px solid var(--c-rule); background: var(--c-surface); padding: var(--s4); }
.ops-bar { display: flex; height: 26px; border: 1px solid var(--c-rule-strong); }
.ops-bar span {
  display: block; height: 100%;
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 700;
  color: #FFFFFF; text-align: center; line-height: 26px; overflow: hidden;
}
.ops-bar .v-ok   { background: var(--c-ok); }
.ops-bar .v-weak { background: var(--c-warn);
  background-image: repeating-linear-gradient(45deg,
    rgba(255,255,255,0.34) 0 3px, rgba(255,255,255,0) 3px 7px); }
.ops-bar .v-null { background: var(--c-null);
  background-image: repeating-linear-gradient(90deg,
    rgba(255,255,255,0.30) 0 1px, rgba(255,255,255,0) 1px 4px); }
.ops-key {
  display: flex; flex-wrap: wrap; gap: var(--s5); margin-top: var(--s3);
  font-family: var(--f-mono); font-size: var(--t-micro); color: var(--c-ink-2);
}
.ops-key b { font-weight: 700; color: var(--c-ink); }

/* ------------------------------------------------------------------ log block */
.ops-log {
  font-family: var(--f-mono); font-size: var(--t-micro); line-height: 1.55;
  white-space: pre; overflow-x: auto;
  background: var(--c-chassis); color: var(--c-ink-2);
  border: 1px solid var(--c-rule); border-left: 3px solid var(--c-rule-strong);
  padding: var(--s3) var(--s4); margin: var(--s3) 0;
}
.ops-cellmap {
  font-family: var(--f-mono); font-size: 18px; line-height: 1.5; letter-spacing: 0.12em;
  white-space: pre; background: var(--c-surface); color: var(--c-ink);
  border: 1px solid var(--c-rule); padding: var(--s3) var(--s4);
}

/* --------------------------------------------------------------- frame labels */
.ops-frame {
  display: flex; align-items: baseline; gap: var(--s2);
  border-bottom: 1px solid var(--c-rule); padding-bottom: var(--s1); margin-bottom: var(--s2);
}
.ops-frame .tag {
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 700;
  letter-spacing: 0.10em; color: #FFFFFF; background: var(--c-ink);
  padding: 1px var(--s2);
}
.ops-frame .role {
  font-family: var(--f-mono); font-size: var(--t-micro); font-weight: 600; color: var(--c-ink);
}
.ops-frame .dim { margin-left: auto; font-family: var(--f-mono);
  font-size: var(--t-micro); color: var(--c-ink-3); }
[data-testid="stImage"] img { border: 1px solid var(--c-rule-strong); display: block; }
[data-testid="stImage"] figcaption, [data-testid="stImageCaption"] {
  font-family: var(--f-mono); font-size: var(--t-micro); color: var(--c-ink-3);
  text-align: left; padding-top: var(--s1);
}

/* ------------------------------------------------------------------- sidebar */
[data-testid="stSidebar"] {
  background: var(--c-chassis);
  border-right: 2px solid var(--c-rule-strong);
}
[data-testid="stSidebar"] [data-testid="stSidebarUserContent"] { padding-top: var(--s4); }
[data-testid="stSidebar"] label, [data-testid="stSidebar"] .stRadio label p {
  font-size: var(--t-micro); color: var(--c-ink-2);
}
.ops-side-h {
  font-family: var(--f-mono); font-size: var(--t-label); font-weight: 700;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--c-ink);
  border-bottom: 2px solid var(--c-rule-strong);
  padding-bottom: var(--s1); margin: var(--s5) 0 var(--s3) 0;
}
.ops-side-h:first-child { margin-top: 0; }
.ops-side-kv {
  font-family: var(--f-mono); font-size: var(--t-micro); color: var(--c-ink-2);
  line-height: 1.6;
}
.ops-side-kv b { color: var(--c-ink); font-weight: 700; }

/* ------------------------------------------------------------------- widgets */
[data-testid="stSidebar"] .stButton > button, .stButton > button {
  border-radius: 2px; font-family: var(--f-mono); font-weight: 700;
  font-size: var(--t-micro); letter-spacing: 0.10em; text-transform: uppercase;
  padding: var(--s3) var(--s4);
}
[data-testid="stBaseButton-primary"] { border: 1px solid #163establish; } /* see note below */
[data-testid="stBaseButton-primary"] { border: 1px solid #163A59; }
[data-testid="stBaseButton-secondary"] {
  background: var(--c-surface); border: 1px solid var(--c-rule-strong); color: var(--c-ink);
}
[data-baseweb="select"] > div, [data-testid="stTextInput"] input,
[data-testid="stNumberInput"] input {
  border-radius: 2px; font-family: var(--f-mono); font-size: var(--t-micro);
}
[data-testid="stSelectbox"] div[data-baseweb="select"] > div { background: var(--c-surface); }

/* Streamlit's own alerts, kept for st.info/st.error paths, restyled to match
   the verdict rail: square, hairline, left rule, no pill. */
[data-testid="stAlert"] {
  border-radius: 0; border: 1px solid var(--c-rule); border-left: 4px solid var(--c-rule-strong);
  padding: var(--s3) var(--s4);
}
[data-testid="stAlert"] p { font-size: var(--t-body); color: var(--c-ink-2); }
[data-testid="stAlertContentInfo"]    { border-left-color: var(--c-accent); }
[data-testid="stAlertContentWarning"] { border-left-color: var(--c-warn); }
[data-testid="stAlertContentError"]   { border-left-color: var(--c-stop); }
[data-testid="stAlertContentSuccess"] { border-left-color: var(--c-ok); }

/* dataframes: mono, tabular, square, readable header */
[data-testid="stDataFrame"] { border: 1px solid var(--c-rule); border-radius: 0; }
[data-testid="stDataFrame"] * {
  font-family: var(--f-mono) !important;
  font-variant-numeric: tabular-nums;
  font-size: var(--t-micro) !important;
}

[data-testid="stExpander"] details {
  border: 1px solid var(--c-rule); border-radius: 0; background: var(--c-surface);
}
[data-testid="stExpander"] summary {
  font-family: var(--f-mono); font-size: var(--t-micro); font-weight: 700;
  letter-spacing: 0.06em; text-transform: uppercase; color: var(--c-ink);
}
hr, [data-testid="stDivider"] { border-color: var(--c-rule); margin: var(--s5) 0; }
[data-testid="stSpinner"] p { font-family: var(--f-mono); font-size: var(--t-micro); }
::selection { background: var(--c-accent-soft); }
</style>
"""

result.config_toml:
// ============================================================================
// .streamlit/config.toml   (create the .streamlit/ directory at the repo root —
// it does not exist today; `ls .streamlit` returns nothing)
//
// BLOCK A below is the safe core. Every key in it has existed in Streamlit for
// many versions and will not stop the app from starting.
//
// BLOCK B is commented out ON PURPOSE. requirements.txt pins streamlit==1.62.0
// and streamlit is NOT installed in the environment I audited from
// (`pip show streamlit` -> "Package(s) not found"), so I could not verify these
// key names against the actual build. Some Streamlit versions merely warn on an
// unrecognised config key; others refuse to start. Refusing to start is a Gate 4
// failure, and Gate 4 is "3 consecutive runs, no crashes".
//
// BEFORE uncommenting Block B, run this and delete any key it does not list:
//
//   python -c "from streamlit import config; config.get_config_options(); \
//              print('\n'.join(k for k in config.get_config_options() \
//              if k.startswith('theme')))"
//
// Nothing in Block B is required. Every visual effect it produces is also
// produced by the CSS block, so deleting all of it costs exactly nothing.
// ============================================================================

# ---------------------------------------------------------------- BLOCK A ----
[theme]
base                     = "light"
# The only element that gets the accent: the Align button.
primaryColor             = "#14487F"
# Paper, not pure white — pure white blooms under a bright projector lamp.
backgroundColor          = "#F7F7F4"
# Sidebar, table headers, code blocks: the control-panel field.
secondaryBackgroundColor = "#ECEBE6"
textColor                = "#14171A"
# Deliberately the legacy-safe literal, NOT a font stack. Older Streamlit only
# accepts "sans serif" | "serif" | "monospace" here and errors on anything else.
# The real faces are set in the CSS block, which works on every version.
font                     = "sans serif"

[browser]
# Invariant 3: wifi is OFF at the demo. Usage stats are a network call on
# startup. Off is both correct and one less thing to time out.
gatherUsageStats = false

[client]
# Removes the "Deploy" button and the developer items from the top-right menu.
# The Deploy button is the single most "this is a web app" element on screen.
toolbarMode = "minimal"

[server]
# No filesystem watcher during the demo. A stray Ctrl+S in an open editor must
# not rerun the script while a judge is looking at a result.
fileWatcherType = "none"
# Explicit: nothing is served from the network, and there is nothing to serve.
enableStaticServing = false

[logger]
level = "warning"


# ---------------------------------------------------------------- BLOCK B ----
# VERIFY WITH THE COMMAND ABOVE BEFORE UNCOMMENTING. Optional, not required.
#
# [theme]
# baseRadius               = "none"     # square corners on every widget
# borderColor              = "#C9C7BF"
# showWidgetBorder         = true
# showSidebarBorder        = true
# linkColor                = "#14487F"
# codeBackgroundColor      = "#ECEBE6"
# baseFontSize             = 17
# font        = "\"Segoe UI\", \"Segoe UI Variable Text\", system-ui, Arial, sans-serif"
# headingFont = "\"Segoe UI\", \"Segoe UI Variable Text\", system-ui, Arial, sans-serif"
# codeFont    = "Consolas, \"Cascadia Mono\", \"DejaVu Sans Mono\", \"Courier New\", monospace"
#
# [theme.sidebar]
# backgroundColor          = "#ECEBE6"
# secondaryBackgroundColor = "#E2E0D9"
# borderColor              = "#C9C7BF"
# textColor                = "#14171A"

