/* ==========================================================================
   SIH26166 — "Reference Frame". ONE injected style block.

   Injected once, immediately after st.set_page_config(), as:

       st.html(SKIN.replace("__BASE_PX__", "19px" if projector else "17px"))

   .replace() and not .format() — the block is full of literal { } braces.

   DESIGN RULE, and it is the important one: this skin must not DEPEND on
   styling Streamlit's internals. Everything load-bearing is on classes we
   author ourselves in our own HTML (.idplate, .seclabel, .readout, .verdict,
   .mt, .legend, .platecap). The blocks marked  [FRAGILE]  target Streamlit's
   own data-testids; if a Streamlit upgrade breaks one, the page degrades to
   "slightly more default-looking" and never to "broken". Do not move anything
   load-bearing into a [FRAGILE] block.
   ========================================================================== */

:root {
  /* ---- ground -------------------------------------------------------- */
  --ink:        #14171A;   /* body text            16.6:1 on --ground      */
  --ink-mute:   #5A5D63;   /* captions, units       5.7:1                  */
  --ink-faint:  #7C8087;   /* metadata, disabled                           */
  --ground:     #F7F7F4;   /* page field (paper, not pure white)           */
  --panel:      #ECEBE6;   /* sidebar, table header                        */
  --panel-2:    #E2E0D9;   /* nested / inset                               */
  --plate:      #E8E7E2;   /* behind image plates                          */
  --rule:       #C9C7BF;   /* hairline                                     */
  --rule-hard:  #8C8A82;   /* section rule                                 */

  /* ---- signal. Four colours. No tints, no pastels. ------------------- */
  --accent:     #14487F;   /* interactive. ONE element uses it.     8.4:1  */
  --ok:         #146B3C;   /* verified / PASS                       6.0:1  */
  --caution:    #A8560A;   /* weak / fallback used                  4.7:1  */
  --fail:       #A3231E;   /* contradicted / FAIL / no transform    6.8:1  */

  /* ---- type ---------------------------------------------------------- */
  /* Numbers. Consolas ships with every Windows since Vista; Cascadia Mono
     with Win11. Slashed zero, tabular by construction. Never a web font —
     wifi is off, a CDN face would silently fall back mid-demo.            */
  --mono: Consolas, "Cascadia Mono", "DejaVu Sans Mono", "Liberation Mono",
          Menlo, Monaco, "Courier New", monospace;
  /* Prose. Segoe UI first and explicit, so a different laptop renders the
     same page rather than resolving system-ui to something else.          */
  --sans: "Segoe UI", "Segoe UI Variable Text", system-ui, -apple-system,
          Roboto, "Helvetica Neue", Arial, "Liberation Sans", sans-serif;

  /* ---- space. 4px base. --------------------------------------------- */
  --s1: 4px;  --s2: 8px;  --s3: 12px; --s4: 16px;
  --s6: 24px; --s8: 32px; --s12: 48px; --s16: 64px;

  --hatch: repeating-linear-gradient(45deg,
            transparent 0 4px, rgba(20,23,26,.42) 4px 6px);
}

/* Streamlit is rem-based, so this one line scales every widget, gutter and
   control together. It is the projector knob. 17px normal / 19px projected. */
html { font-size: __BASE_PX__; }

/* ==========================================================================
   1. DELETE THE WEB APP                                        [FRAGILE]
   ========================================================================== */
/* stDecoration is a literal rainbow GRADIENT bar across the top of the page.
   It is the first thing on screen and it must not be.                       */
[data-testid="stDecoration"] { display: none !important; }
[data-testid="stToolbar"]    { display: none !important; }
