   ========================================================================== */
.idplate { border-bottom: 3px solid var(--ink); padding-bottom: var(--s3); margin-bottom: var(--s6); }
.idplate__name {
  font-family: var(--sans); font-size: 1.5rem; font-weight: 600;
  letter-spacing: -0.01em; line-height: 1.15;
}
.idplate__ps {
  font-family: var(--mono); font-size: .72rem; font-weight: 400;
  letter-spacing: .10em; color: var(--ink-mute);
