}
.idplate__sub { font-size: .92rem; color: var(--ink-mute); margin-top: var(--s1); max-width: 78ch; }
.idplate__strip { margin-top: var(--s3); display: flex; flex-wrap: wrap; gap: var(--s2); }
.tag {
  font-family: var(--mono); font-size: .70rem; letter-spacing: .09em;
  text-transform: uppercase; color: var(--ink-mute);
