/* ==========================================================================
   5. PRIMARY READOUT   (replaces the st.success at line 571)
   The template is the point: value, unit, grid, metres — or an explicit
   void with a reason. A pixel figure cannot be rendered here without its
   grid, because the markup has nowhere to put it otherwise.
   ========================================================================== */
.readout {
  border-top: 3px solid var(--ink); border-bottom: 1px solid var(--rule);
  padding: var(--s3) 0 var(--s4) 0; margin: var(--s4) 0;
}
.readout__k {
  font-family: var(--mono); font-size: .72rem; letter-spacing: .11em;
