}
.readout__u { font-size: 1.05rem; font-weight: 400; color: var(--ink-mute); margin-left: var(--s2); }
.readout__x { font-family: var(--mono); font-size: .86rem; color: var(--ink); margin-top: var(--s2); }
.readout__x b { font-weight: 600; }
.readout--void .readout__v { color: var(--ink-faint); font-size: 2.2rem; }
.readout--void .readout__x { color: var(--caution); }

/* ==========================================================================
   6. VERDICT STRIP   (replaces st.success/st.warning/st.error, lines 433-453)
   State is carried by the WORD first and the bar second. Never colour alone.
   ========================================================================== */
.verdict {
  display: flex; gap: var(--s4); align-items: flex-start;
  background: var(--panel); border-left: 4px solid var(--ink-mute);
  padding: var(--s3) var(--s4); margin: var(--s4) 0;
}
.verdict__word {
  font-family: var(--mono); font-size: .74rem; font-weight: 700;
  letter-spacing: .11em; text-transform: uppercase;
  white-space: nowrap; padding-top: 2px; min-width: 15ch;
}
.verdict__body { font-size: .94rem; line-height: 1.5; max-width: 74ch; }
.verdict__body code { background: var(--panel-2) !important; }
.verdict--ok      { border-left-color: var(--ok); }
.verdict--ok      .verdict__word { color: var(--ok); }
.verdict--caution { border-left-color: var(--caution); }
.verdict--caution .verdict__word { color: var(--caution); }
.verdict--fail    { border-left-color: var(--fail); }
.verdict--fail    .verdict__word { color: var(--fail); }

/* ==========================================================================
   7. METRICS TABLE   (replaces the st.dataframe at line 566)
   ========================================================================== */
.mt { width: 100%; border-collapse: collapse; margin-top: var(--s2); }
.mt th {
  font-family: var(--mono); font-size: .68rem; font-weight: 600;
  letter-spacing: .10em; text-transform: uppercase; color: var(--ink-mute);
  text-align: left; padding: var(--s2) var(--s3);
  border-bottom: 2px solid var(--ink); white-space: nowrap;
}
.mt td {
  padding: var(--s3); border-bottom: 1px solid var(--rule);
  font-size: .92rem; vertical-align: baseline;
}
.mt tr:last-child td { border-bottom: 1px solid var(--rule-hard); }
.mt .k { font-family: var(--mono); font-size: .90rem; white-space: nowrap; }
.mt .num {
  font-family: var(--mono); font-size: 1.06rem; font-weight: 600;
  text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap;
}
.mt .num--void { font-weight: 400; color: var(--ink-faint); text-align: left; font-size: .88rem; }
.mt .u { font-family: var(--mono); font-size: .80rem; color: var(--ink-mute); padding-left: 6px; }
.mt .m { color: var(--ink-mute); }
.mt .g { font-family: var(--mono); font-size: .84rem; white-space: nowrap; }
.mt .g b { font-weight: 700; letter-spacing: .06em; }
.mt .g--pass b { color: var(--ok); }
.mt .g--fail  b { color: var(--fail); }
.mt .g--none  { color: var(--ink-faint); }
/* full-precision value on hover; the display rounding hides nothing */
.mt .num[title] { cursor: help; }

/* ==========================================================================
   8. RELIABILITY LEGEND   (replaces the three st.metric calls, lines 524-527)
   The swatch hatch is byte-for-byte the pattern drawn into the overlay.
   Colour, pattern AND letter — three channels for three states.
   ========================================================================== */
.legend { list-style: none; margin: var(--s2) 0 var(--s4) 0; padding: 0;
          display: flex; flex-wrap: wrap; gap: var(--s8); }
.legend li { display: flex; align-items: center; gap: var(--s3); }
.sw { width: 30px; height: 30px; border: 2px solid var(--ink); flex: none; }
.sw--v { background: #7FBF9C; }                             /* solid          */
.sw--w { background: #E0B071; background-image: var(--hatch); }  /* + 45 hatch */
.sw--n { background: var(--plate); border-style: dotted; }  /* no tint at all */
.legend__g {
  font-family: var(--mono); font-size: 1.15rem; font-weight: 700;
  width: 1.4ch; text-align: center;
}
.legend__t { font-size: .90rem; line-height: 1.25; }
.legend__t b { display: block; font-family: var(--mono); font-size: 1.15rem;
               font-weight: 600; font-variant-numeric: tabular-nums; }
.legend__t span { color: var(--ink-mute); font-size: .80rem; }

/* ==========================================================================
   9. IMAGE PLATES
   ========================================================================== */
[data-testid="stImage"] img {                                /* [FRAGILE] */
  border: 1px solid var(--ink); background: var(--plate); display: block;
}
[data-testid="stImageCaption"] {                             /* [FRAGILE] */
