.platecap b { color: var(--ink); text-transform: uppercase; letter-spacing: .10em; }

/* ==========================================================================
   10. SIDEBAR — the control panel                            [FRAGILE]
   ========================================================================== */
[data-testid="stSidebar"] {
  background: var(--panel) !important; border-right: 1px solid var(--rule-hard);
}
[data-testid="stSidebar"] [data-testid="stSidebarUserContent"] { padding-top: var(--s6); }
