}
[data-testid="stSidebar"] hr { border-color: var(--rule); margin: var(--s4) 0; }

/* Buttons: square, flat, bordered. The accent appears here and nowhere else. */
.stButton > button {
  font-family: var(--mono) !important; font-size: .80rem !important;
  font-weight: 600 !important; letter-spacing: .11em; text-transform: uppercase;
  border: 1px solid var(--ink) !important; background: #FFFFFF; color: var(--ink);
  padding: var(--s3) var(--s4) !important; transition: none !important;
}
