                              background: var(--panel) !important; }

/* Slider (the swipe seam) — hairline track, square thumb. */
[data-testid="stSlider"] [role="slider"] { border-radius: 0 !important; background: var(--ink) !important; }
[data-testid="stSlider"] [data-testid="stThumbValue"] { font-family: var(--mono) !important; font-size: .74rem !important; }

/* ==========================================================================
   11. REMAINING STREAMLIT WIDGETS                            [FRAGILE]
   ========================================================================== */
/* Any st.metric that survives, and the change-candidates dataframe. */
[data-testid="stMetricValue"] { font-family: var(--mono) !important; font-variant-numeric: tabular-nums; }
[data-testid="stMetricLabel"] p {
  font-family: var(--mono) !important; font-size: .70rem !important;
  letter-spacing: .10em; text-transform: uppercase; color: var(--ink-mute) !important;
}
[data-testid="stDataFrame"] { border: 1px solid var(--rule); }
[data-testid="stDataFrame"] * { font-family: var(--mono) !important; font-size: .84rem !important; }

/* Alerts that remain (sidebar tier warnings, error paths) — flattened to the
   same verdict language rather than pastel rounded boxes. */
[data-testid="stAlert"], [data-testid="stAlertContainer"], [data-testid="stNotification"] {
  border: 1px solid var(--rule) !important; border-left: 4px solid var(--ink-mute) !important;
  background: var(--panel) !important; color: var(--ink) !important;
  padding: var(--s3) var(--s4) !important;
}
[data-testid="stAlert"] svg, [data-testid="stAlertContainer"] svg { display: none !important; }
[data-testid="stAlertContainer"][data-baseweb="notification"][kind="error"],
div[data-testid="stAlert"][data-baseweb="notification"][kind="error"]   { border-left-color: var(--fail) !important; }
[data-testid="stAlertContainer"][kind="warning"] { border-left-color: var(--caution) !important; }
[data-testid="stAlertContainer"][kind="success"] { border-left-color: var(--ok) !important; }
[data-testid="stAlertContainer"][kind="info"]    { border-left-color: var(--accent) !important; }

/* Expanders: a labelled drawer, not a card. */
[data-testid="stExpander"] details {
  border: 1px solid var(--rule) !important; background: transparent !important;
}
[data-testid="stExpander"] summary p {
  font-family: var(--mono) !important; font-size: .74rem !important;
  font-weight: 600 !important; letter-spacing: .09em; text-transform: uppercase;
  color: var(--ink) !important;
}
[data-testid="stSpinner"] p { font-family: var(--mono) !important; font-size: .82rem !important; }
hr, [data-testid="stDivider"] hr { border: none; border-top: 1px solid var(--rule); }

/* ==========================================================================
   12. LAST-RESORT LEGIBILITY
   If the projector is worse than expected, the OS "increase contrast" setting
   pushes the design to maximum ink without touching the layout.
   ========================================================================== */
@media (prefers-contrast: more) {
