/* a plate on paper needs an edge, or a dark lunar frame floats */
.stImage img{
  border:1px solid var(--rule-mid); background:var(--paper-3); display:block;
}
[data-testid="stImageCaption"]{
  font-family:var(--sans)!important; font-size:14px!important;
  color:var(--ink-3)!important;
}
/* the 3-up contact sheet is reference material, not the hero */
.contact-sheet [data-testid="stImage"] img{
  max-height:250px; width:auto; object-fit:contain;
}

/* --- 7. margin notes (replace st.success / st.warning / st.info) --------- */
.note{
  border-left:3px solid var(--rule-strong);
  padding:var(--s1) 0 var(--s1) var(--s4);
  margin:var(--s4) 0 var(--s5) 0; max-width:var(--measure);
}
.note-tag{
  display:block; font-family:var(--mono); font-size:12px; font-weight:700;
  letter-spacing:.10em; text-transform:uppercase; color:var(--ink-3);
  margin-bottom:var(--s1);
}
.note-body{font-size:17px;color:var(--ink);}
.note-body p{margin:0 0 var(--s2) 0;}
.note--result      {border-left-color:var(--st-verified);}
.note--result   .note-tag{color:var(--st-verified);}
.note--warning     {border-left-color:var(--st-weak);}
.note--warning  .note-tag{color:var(--st-weak);}
.note--failed      {border-left-color:var(--alarm);}
.note--failed   .note-tag{color:var(--alarm);}
.note--gap         {border-left-color:var(--st-none);}
.note--gap      .note-tag{color:var(--st-none);}
.note--note        {border-left-color:var(--rule-strong);}

/* any st.alert that survives is flattened to the same margin note */
[data-testid="stAlert"], [data-testid="stAlertContainer"]{
  background:transparent!important; border:0!important; border-radius:0!important;
  border-left:3px solid var(--rule-strong)!important;
  padding:var(--s1) 0 var(--s1) var(--s4)!important;
  color:var(--ink)!important; box-shadow:none!important;
  max-width:var(--measure);
}
[data-testid="stAlert"] p{font-family:var(--serif);font-size:17px;}

/* --- 8. principal result ------------------------------------------------ */
/* Invariant 2 rendered as furniture: value, grid, metres, always together. */
.principal{
  border-top:2px solid var(--ink); border-bottom:2px solid var(--ink);
  background:var(--paper-3);
  padding:var(--s5) var(--s5); margin:var(--s5) 0 var(--s6) 0;
  max-width:var(--measure);
}
.principal-label{
  font-family:var(--sans); font-size:12px; font-weight:600;
  letter-spacing:.11em; text-transform:uppercase; color:var(--ink-3);
  margin-bottom:var(--s2);
}
.principal-value{
  font-family:var(--mono); font-variant-numeric:tabular-nums lining-nums;
  font-size:34px; font-weight:700; line-height:1.05; color:var(--ink);
  letter-spacing:-.01em;
}
.principal-value .unit{font-size:20px;font-weight:400;color:var(--ink-2);}
.principal-note{
  font-family:var(--sans); font-size:15px; color:var(--ink-2);
  margin-top:var(--s2);
}
.principal-note b{font-weight:700;color:var(--ink);}

/* --- 9. report tables --------------------------------------------------- */
/* Tufte: horizontal rules only, no verticals, no zebra, numbers right-aligned
   and tabular so decimal points line up down the column. */
table.report-table{
  border-collapse:collapse; width:100%; margin:var(--s4) 0 var(--s3) 0;
  font-size:16px;
}
table.report-table caption{
  caption-side:top; text-align:left;
  font-family:var(--sans); font-size:14px; color:var(--ink-3);
  padding-bottom:var(--s3); border-bottom:1px solid var(--rule);
  margin-bottom:var(--s2);
}
table.report-table caption .tabno{font-weight:700;color:var(--ink-2);margin-right:.55em;}
table.report-table th{
  font-family:var(--sans); font-size:12px; font-weight:600;
  letter-spacing:.09em; text-transform:uppercase; color:var(--ink-3);
  text-align:left; padding:var(--s2) var(--s4) var(--s2) 0;
  border-bottom:1.5px solid var(--ink-2); vertical-align:bottom;
}
table.report-table td{
  padding:var(--s3) var(--s4) var(--s3) 0;
  border-bottom:1px solid var(--rule); vertical-align:baseline;
  color:var(--ink);
}
table.report-table tbody th[scope="row"]{
  font-family:var(--mono); font-size:15px; font-weight:400;
  text-transform:none; letter-spacing:0; color:var(--ink);
  border-bottom:1px solid var(--rule); padding-right:var(--s5);
  white-space:nowrap;
}
table.report-table td.num, table.report-table th.num{
  font-family:var(--mono); font-variant-numeric:tabular-nums lining-nums;
  text-align:right; white-space:nowrap; padding-right:var(--s6);
}
table.report-table td.meaning{
  font-family:var(--serif); color:var(--ink-2); font-size:16px;
}
table.report-table tbody tr:last-child td,
table.report-table tbody tr:last-child th{border-bottom:2px solid var(--ink-2);}
/* PASS / FAIL: the WORD is the channel. Colour and weight only reinforce it. */
.verdict{
  font-family:var(--mono); font-size:14px; letter-spacing:.06em;
  white-space:nowrap;
}
.verdict .thr{color:var(--ink-3);letter-spacing:0;}
.verdict.pass{color:var(--st-verified);}
.verdict.fail{color:var(--alarm);font-weight:700;
              border-left:3px solid var(--alarm);padding-left:var(--s2);}
.verdict.na{color:var(--ink-3);}

/* --- 10. reliability legend --------------------------------------------- */
/* Three channels per state: swatch PATTERN, the WORD, and the count.
   Hue is the fourth and least load-bearing. Nothing here is colour-only. */
table.legend{border-collapse:collapse;width:100%;margin:var(--s4) 0;font-size:16px;}
table.legend td{
  padding:var(--s3) var(--s4) var(--s3) 0;
  border-bottom:1px solid var(--rule); vertical-align:top;
}
table.legend tr:first-child td{border-top:1.5px solid var(--ink-2);}
.swatch{
  width:44px;height:26px;display:block;
  border:2px solid var(--rule-mid);background:var(--paper-3);
}
.swatch--verified{
  border-color:var(--st-verified);border-style:solid;background:var(--paper-3);
}
.swatch--weak{
  border-color:var(--st-weak);border-style:dashed;
  background:repeating-linear-gradient(45deg,
    var(--st-weak) 0 2px, transparent 2px 7px), var(--paper-3);
}
.swatch--none{
  border-color:var(--st-none);border-style:dotted;
  background:radial-gradient(var(--st-none) 1px, transparent 1.2px) 0 0/6px 6px,
             var(--paper-2);
}
.legend-word{
  font-family:var(--sans); font-size:13px; font-weight:700;
  letter-spacing:.10em; text-transform:uppercase; white-space:nowrap;
}
.legend-word.verified{color:var(--st-verified);}
.legend-word.weak{color:var(--st-weak);}
.legend-word.none{color:var(--st-none);}
.legend-count{
  font-family:var(--mono); font-variant-numeric:tabular-nums lining-nums;
  font-size:20px; font-weight:700; color:var(--ink); white-space:nowrap;
}
.legend-count .of{font-size:14px;font-weight:400;color:var(--ink-3);}
.legend-def{font-family:var(--serif);font-size:16px;color:var(--ink-2);}

/* --- 11. footnotes and colophon ----------------------------------------- */
ol.notes{
  max-width:var(--measure); margin:var(--s4) 0; padding-left:0;
  list-style:none; counter-reset:note;
}
ol.notes li{
  counter-increment:note; position:relative;
  padding-left:var(--s6); margin-bottom:var(--s3);
  font-size:15px; line-height:1.5; color:var(--ink-2);
}
ol.notes li::before{
  content:counter(note) "."; position:absolute; left:0;
  font-family:var(--mono); font-size:13px; color:var(--ink-3);
}
.colophon-foot{
  border-top:1px solid var(--rule-strong);
  margin-top:var(--s8); padding-top:var(--s3);
  font-family:var(--mono); font-size:13px; color:var(--ink-3);
  max-width:var(--measure);
}
code, .stCode, pre{
  font-family:var(--mono)!important; font-size:15px;
  background:var(--paper-3); border-radius:0;
}
.stMain [data-testid="stMarkdownContainer"] code{
  padding:1px 4px; border:1px solid var(--rule);
}

/* --- 12. sidebar = run parameters, sans throughout ----------------------- */
[data-testid="stSidebar"]{
  background:var(--paper-2);
  border-right:1px solid var(--rule-strong);
}
[data-testid="stSidebar"] *{font-family:var(--sans)!important;}
[data-testid="stSidebarUserContent"], [data-testid="stSidebarContent"]{
  padding-top:var(--s6); padding-left:var(--s5); padding-right:var(--s5);
}
[data-testid="stSidebar"] h1,[data-testid="stSidebar"] h2,
[data-testid="stSidebar"] h3{
  font-size:12px!important; font-weight:600!important;
  letter-spacing:.11em; text-transform:uppercase; color:var(--ink-3)!important;
  border-bottom:1px solid var(--rule); padding-bottom:var(--s2);
  margin:0 0 var(--s3) 0!important;
}
[data-testid="stSidebar"] .stCaption,
[data-testid="stSidebar"] [data-testid="stCaptionContainer"]{font-size:13px!important;}
[data-testid="stSidebar"] code{
  font-family:var(--mono)!important; background:var(--paper-3);
  border:1px solid var(--rule); padding:1px 4px;
}
[data-testid="stSidebar"] hr{margin:var(--s5) 0;}

/* --- 13. widgets: square, quiet, sans ----------------------------------- */
.stButton > button, .stDownloadButton > button{
  font-family:var(--sans); font-size:14px; font-weight:600;
  letter-spacing:.04em; border-radius:0!important; box-shadow:none!important;
  border:1px solid var(--accent); padding:var(--s2) var(--s5);
  transition:none;
}
.stButton > button[kind="primary"],
.stButton > button[data-testid="baseButton-primary"]{
  background:var(--accent); color:#FFFFFF; border-color:var(--accent);
}
.stButton > button[kind="primary"]:hover{background:#16304A;color:#FFFFFF;}
.stButton > button:not([kind="primary"]){background:var(--paper);color:var(--accent);}
.stButton > button:not([kind="primary"]):hover{background:var(--paper-3);}
.stButton > button:disabled{
  border-color:var(--rule-mid); color:var(--ink-3); background:var(--paper-2);
}
[data-testid="stWidgetLabel"] p, .stWidgetLabel p{
  font-family:var(--sans)!important; font-size:13px!important; font-weight:600;
  letter-spacing:.02em; color:var(--ink-2)!important;
}
.stSelectbox div[data-baseweb="select"] > div,
.stTextInput input, .stNumberInput input{
  border-radius:0!important; border-color:var(--rule-mid)!important;
  font-family:var(--sans);
}
.stSlider [data-baseweb="slider"]{padding-top:var(--s2);}
[data-testid="stFileUploaderDropzone"]{
  border-radius:0!important; border:1px dashed var(--rule-mid)!important;
  background:var(--paper)!important;
}
[data-testid="stExpander"]{
  border:0!important; border-top:1px solid var(--rule)!important;
  border-radius:0!important; box-shadow:none!important; background:transparent;
}
[data-testid="stExpander"] summary, [data-testid="stExpander"] details > summary{
  font-family:var(--sans)!important; font-size:13px!important; font-weight:600;
  letter-spacing:.06em; text-transform:uppercase; color:var(--ink-3);
  padding-left:0;
}
/* st.dataframe renders to a CANVAS - it takes colour from config.toml, not
   from here. All CSS can do is frame it and stop it sprawling. */
[data-testid="stDataFrame"], .stDataFrame{
  border:1px solid var(--rule-mid); border-radius:0;
}
[data-testid="stMetric"]{
  background:transparent; border:0; border-left:3px solid var(--rule-strong);
  padding-left:var(--s4); border-radius:0;
}
[data-testid="stMetricValue"]{
  font-family:var(--mono)!important; font-variant-numeric:tabular-nums lining-nums;
  font-size:28px!important; color:var(--ink)!important;
}

/* --- 14. print: the report is also a PDF -------------------------------- */
/* Save-to-PDF is the fallback if the projector dies, and it is the artefact a
   judge can be handed. Ctrl+P -> Save as PDF -> background graphics ON. */
@media print{
  [data-testid="stSidebar"], [data-testid="stHeader"],
  .stButton, .stSlider, [data-testid="stFileUploader"]{display:none!important;}
  [data-testid="stMainBlockContainer"]{max-width:100%;padding:0;}
  .stApp, html, body{background:#FFFFFF;}
  .figcap, .principal, table.report-table, table.legend, .stImage{
    break-inside:avoid; page-break-inside:avoid;
  }
  .section{break-after:avoid; page-break-after:avoid;}
  a{color:var(--ink);text-decoration:none;}
}

/* --- 15. very wide projectors ------------------------------------------- */
@media (min-width:1900px){
  html, body, .stApp{font-size:18px;}
  :root{--page:1280px;}
}
